 z.input[0]=x;z.input[1]=y;z.output[0]=out.X;z.output[1]=out.Y;z.center[0]=X;z.center[1]=Y;z.anchor[0]=m.base.vertex[seed][0].n;z.anchor[1]=m.base.vertex[seed][1].n;z.L=out.L;z.radius=out.radius;z.residual=residual;z.inside=out.inside;for(int a=0;a<3;a++)z.lambda[a]=lambda[a].v;for(int k=0;k<2;k++)z.position[k]=q.position[k];for(int k=0;k<4;k++)z.F[k]=q.F[k];z.J=q.J;need(out.inside,"vertex-seed inverse contraction box strictly inside original source");return out;
