// Selection only: the resulting binary64 direction is subsequently proved
// with outward Q128 gradient intervals. No claim of an optimal direction
// or of absence of a direction relies on these long-double angles.
static std::array<Q,2> gap_direction(const std::vector<target::Plane>&planes,uint64_t mask,Q L){
 const long double pi=acosl(-1.L);std::vector<std::pair<long double,long double>>forbidden;
 for(size_t i=0;i<planes.size();i++)if(mask&(uint64_t(1)<<i)){long double nx=planes[i].n[0].n,ny=planes[i].n[1].n;long double ratio=(fabsl(nx)+fabsl(ny))*static_cast<long double>(L)/hypotl(nx,ny);need(ratio<1,"sufficient normal cone permits a direction");long double w=asinl(ratio),c=fmodl(atan2l(ny,nx)+pi/2+pi,pi),lo=c-w,hi=c+w;if(lo<0){forbidden.push_back({0,hi});forbidden.push_back({lo+pi,pi});}else if(hi>pi){forbidden.push_back({lo,pi});forbidden.push_back({0,hi-pi});}else forbidden.push_back({lo,hi});}
 need(!forbidden.empty(),"actual nonempty active normals");std::sort(forbidden.begin(),forbidden.end());std::vector<std::pair<long double,long double>>merged;for(auto v:forbidden){if(merged.empty()||v.first>merged.back().second)merged.push_back(v);else merged.back().second=std::max(merged.back().second,v.second);}long double width=-1,angle=0;for(size_t i=0;i<merged.size();i++){long double a=merged[i].second,b=i+1<merged.size()?merged[i+1].first:merged[0].first+pi;if(b-a>width){width=b-a;angle=(a+b)/2;}}need(width>0,"sufficient cone angular gap exists");return {Q(double(cosl(angle))),Q(double(sinl(angle)))};
}
